import json, pathlib

path = pathlib.Path(r'c:\Users\efso office\Desktop\Gemma4GR\data\qa_pairs.jsonl')
pairs = [json.loads(l) for l in path.read_text(encoding='utf-8').splitlines() if l.strip()]
qmap = {p['question']: i for i, p in enumerate(pairs)}

def fa(q, new_a):
    if q in qmap:
        pairs[qmap[q]]['answer'] = new_a
    else:
        print(f'NOT FOUND: {q[:70]}')

def fq(old_q, new_q, new_a=None):
    if old_q in qmap:
        i = qmap[old_q]
        pairs[i]['question'] = new_q
        if new_a:
            pairs[i]['answer'] = new_a
        qmap[new_q] = i
    else:
        print(f'NOT FOUND Q: {old_q[:70]}')

