# ── SAVE ──────────────────────────────────────────────────────────────────────
out = '\n'.join(json.dumps(p, ensure_ascii=False) for p in pairs)
path.write_text(out + '\n', encoding='utf-8')
print(f'Saved. Total pairs: {len(pairs)}')

# ── VERIFY ────────────────────────────────────────────────────────────────────
import re
cyrillic = [p for p in pairs if re.search(r'[Ѐ-ӿ]', p['answer'])]
latin_leak = [(p, re.findall(r'[a-zA-Z]{5,}', p['answer'])) for p in pairs]
latin_leak = [(p, ws) for p, ws in latin_leak if any(w[0].islower() for w in ws)]
# exclude known-good etymology/technical terms
safe = {'online', 'phonological', 'awareness', 'khiar', 'boccale', 'pomodoro', 'decanus', 'Civilis', 'Corpus', 'Juris'}
latin_leak = [(p, ws) for p, ws in latin_leak if any(w not in safe for w in ws if w[0].islower())]
print(f'Remaining Cyrillic: {len(cyrillic)}')
print(f'Remaining Latin leakage (excl. technical): {len(latin_leak)}')
for p, ws in latin_leak[:10]:
    low = [w for w in ws if w[0].islower() and w not in safe]
    if low:
        print(f'  [{p["category"]}] {low} -- Q: {p["question"][:60]}')
